using System;using System.Collections.Generic;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using IdleRestaurant;
public static class RestaurantFamilyEconomyVerification {
 static void Need(bool ok,string why){if(!ok)throw new Exception(why);}
 [MenuItem("Restaurant/Family Game/Verify free economy and simulate progression")]
 public static void Run(){var c=AssetDatabase.LoadAssetAtPath<RestaurantCatalog>(RestaurantProductionBuilder.CatalogPath);var checks=new List<object>();int failed=0;Action<string,Action> test=(name,fn)=>{try{fn();checks.Add(new{name,passed=true,error=""});}catch(Exception e){failed++;checks.Add(new{name,passed=false,error=e.Message});}};
 test("All 40 outlets are sequentially unlockable with earned coins",()=>{var g=new RestaurantGame(c);g.State.cash=1e30;Need(!g.Open(2),"Skipped previous outlet");for(int i=1;i<40;i++)Need(g.Open(i),"Blocked outlet "+i);});
 test("Finite, increasing upgrade prices at every outlet and high repeat ranks",()=>{var g=new RestaurantGame(c);foreach(int rank in new[]{0,60,1000000})for(int i=0;i<40;i++){g.State.outlets[i].rank=rank;for(int card=0;card<9;card++){double previous=0;for(int l=0;l<30;l++){g.State.outlets[i].upgrades[card]=l;double cost=g.Cost(i,card);Need(double.IsFinite(cost)&&cost>=previous&&cost>0,"Invalid cost");previous=cost;}g.State.outlets[i].upgrades[card]=30;Need(double.IsPositiveInfinity(g.Cost(i,card)),"Upgrade cap failed");}Need(double.IsFinite(g.FamilyMealValue(i)),"Infinite payout");}});
 test("All 71 teammates obtainable without purchases or random paid rewards",()=>{var g=new RestaurantGame(c);g.State.gems=71*g.Balance.recruitTickets;for(int i=0;i<71;i++)Need(g.Recruit(0),"Recruit failed");Need(g.State.managerCopies.All(x=>x==1)&&g.State.gems==0,"Incomplete deterministic recruitment cycle");Need(!g.Recruit(0)&&g.State.gems==0,"Tickets became negative");g.State.gems=100;Need(!g.Recruit(0)&&g.State.gems==100,"Completed team consumed tickets");var starter=new RestaurantGame(c);starter.State.cash=200;Need(starter.Open(1),"Starter unlock failed");starter.State.gems=8;Need(starter.Recruit(0)&&starter.State.managerCopies[0]==1&&starter.State.managerCopies[1]==1,"Recruitment duplicated the free starter");});
 test("Every upgrade has a useful economic or service effect",()=>{for(int card=0;card<9;card++){var g=new RestaurantGame(c);double before=card==0?g.OrderDuration(0):card==3?g.WalkingSpeed(0):card==4?g.CookDuration(0):card==6?g.MealDuration(0):g.FamilyPay(0,card/3);g.State.cash=100;Need(g.Buy(card),"Purchase rejected");double after=card==0?g.OrderDuration(0):card==3?g.WalkingSpeed(0):card==4?g.CookDuration(0):card==6?g.MealDuration(0):g.FamilyPay(0,card/3);Need(card==7||before!=after,"No useful effect for "+card);}});
 test("Teammates train with earned tickets, without duplicate requirements",()=>{var g=new RestaurantGame(c);g.State.managerCopies[0]=1;g.State.managerLevels[0]=1;Need(!g.LevelManager(0),"Training without tickets");g.State.gems=3;Need(g.LevelManager(0)&&g.State.managerLevels[0]==2&&g.State.gems==0,"Earned training failed");});
 test("No paid entitlement affects the free economy",()=>{var g=new RestaurantGame(c);double before=g.FamilyIncome(0);g.State.income2=g.State.income3=g.State.premiumOffline=true;g.State.boostUntil=g.Now()+99999;Need(g.AccountIncome==1&&g.FamilyIncome(0)==before,"Legacy paid boost leaked");});
 test("Offline earnings capped at one day and collected once",()=>{var g=new RestaurantGame(c);g.State.utc=1000;double expected=g.NetworkIncome()/60*g.Balance.offlineCapSeconds;g.Resume(1000+3*86400);Need(Math.Abs(g.State.pendingOffline-expected)<1e-7,"Offline cap mismatch");double first=g.ClaimOffline();Need(g.ClaimOffline()==0&&Math.Abs(g.State.cash-first)<1e-7,"Double collection");});
 test("Stars repeat safely and keep the player's money",()=>{var g=new RestaurantGame(c);g.State.cash=123;for(int rank=0;rank<1000;rank++){for(int j=0;j<9;j++)g.State.outlets[0].upgrades[j]=30;g.State.outlets[0].waves=g.State.outlets[0].lastStarWave+g.Balance.starEveryServices;Need(g.Prestige(),"Star locked at "+rank);Need(g.State.cash==123&&g.State.outlets[0].upgrades.All(x=>x==30)&&!g.CanPrestige(0)&&double.IsFinite(g.FamilyMealValue(0)),"Unsafe repeat progression");}Need(g.State.prestigeCoins==1000,"Missing star rewards");});
 test("Research slots and completion cannot consume unavailable currency",()=>{var g=new RestaurantGame(c);g.Now=()=>1000;Need(!g.StartResearch(0)&&!g.AddSlot(),"Granted without funds");g.State.cash=10000;Need(g.StartResearch(0)&&!g.StartResearch(1),"Slot limit ignored");g.Now=()=>2000;g.Tick(.05);Need(g.State.research[0].level==1,"Research never completed");g.State.gems=8;Need(g.AddSlot()&&g.State.slots==2&&g.State.gems==0,"Free ticket slot failed");});
 test("Save checksum, backup and guest reservations survive round trip",()=>{string p=Path.Combine(Path.GetTempPath(),"family-economy-"+Guid.NewGuid()+"/save.json");var g=new RestaurantGame(c);g.BeginService();g.State.outlets[0].service[0].phase=GuestPhase.Eating;g.State.outlets[0].service[0].seat=2;var store=new SaveStore(p);store.Write(g.State);g.State.cash=45;store.Write(g.State);Need(store.Read(out _).outlets[0].service[0].seat==2,"Seat lost");File.WriteAllText(p,"broken");Need(store.Read(out bool recovered).cash==0&&recovered,"Backup not recovered");Directory.Delete(Path.GetDirectoryName(p),true);});
 Directory.CreateDirectory("Verification");File.WriteAllText("Verification/FamilyEconomy.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{utc=DateTime.UtcNow,passed=checks.Count-failed,failed,checks},Newtonsoft.Json.Formatting.Indented));Debug.Log("FAMILY_ECONOMY passed="+(checks.Count-failed)+" failed="+failed);Simulate(c);
 }
 static void Simulate(RestaurantCatalog c){var g=new RestaurantGame(c);g.State.introComplete=true;g.State.guideStep=6;g.State.outlets[0].waves=1;g.State.outlets[0].upgrades[0]=g.State.outlets[0].upgrades[3]=1;g.State.cash=157.8;double seconds=40.4;int next=1,purchases=2;var milestones=new List<object>();int iterations=0;
 // Analytical income forecast only. Actual first service is separately measured by FamilyPlay.
 while(next<40&&seconds<604800&&iterations++<40000){if(g.State.cash>=g.FamilyUnlock(next)){g.Open(next);milestones.Add(new{outlet=next+1,title=c.outlets[next].title,minutes=seconds/60,coins=g.State.cash,upgradesBought=purchases});next++;continue;}
 double income=g.NetworkIncome()/60,best=0;int oi=-1,ci=-1;double price=0;
 for(int i=0;i<next;i++){double before=g.FamilyIncome(i);for(int card=0;card<9;card++){double cost=g.Cost(i,card);if(!double.IsFinite(cost))continue;g.State.outlets[i].upgrades[card]++;double gain=(g.FamilyIncome(i)-before)/60;g.State.outlets[i].upgrades[card]--;double roi=gain/cost;if(roi>best&&roi>1.0/180){best=roi;oi=i;ci=card;price=cost;}}}
 double target=oi>=0?Math.Min(price,g.FamilyUnlock(next)):g.FamilyUnlock(next);if(g.State.cash<target){double wait=(target-g.State.cash)/income;g.State.cash+=wait*income;seconds+=wait;}else if(oi>=0&&g.State.cash>=price){g.State.selected=oi;if(g.Buy(ci))purchases++;}else{seconds++;g.State.cash+=income;}
 }
 File.WriteAllText("Verification/FamilyProgressionForecast.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{utc=DateTime.UtcNow,scope="Analytical forecast from edited balance; not observed playtime. Policy buys upgrades with under 180s forecast payback and opens next outlet when affordable. No research, managers, star ranks or offline rewards. Includes measured 40.4s onboarding, then estimated income.",allOutletsOpened=next==40,totalMinutes=seconds/60,purchases,iterations,milestones},Newtonsoft.Json.Formatting.Indented));
 }
}
